import{_ as a,c as t,o as e,ag as r}from"./chunks/framework.ymCRTBvy.js";const b=JSON.parse('{"title":"2.1_创建无Storyboard的Xcode项目","description":"","frontmatter":{},"headers":[],"relativePath":"swift/uikit/uikit_animation/2.1_创建无Storyboard的Xcode项目.md","filePath":"swift/uikit/uikit_animation/2.1_创建无Storyboard的Xcode项目.md"}'),i={name:"swift/uikit/uikit_animation/2.1_创建无Storyboard的Xcode项目.md"};function d(n,o,l,c,s,p){return e(),t("div",null,o[0]||(o[0]=[r('<h1 id="_2-1-创建无storyboard的xcode项目" tabindex="-1">2.1_创建无Storyboard的Xcode项目 <a class="header-anchor" href="#_2-1-创建无storyboard的xcode项目" aria-label="Permalink to &quot;2.1_创建无Storyboard的Xcode项目&quot;">​</a></h1><h2 id="告别storyboard-纯代码项目的魅力-✨" tabindex="-1">告别Storyboard：纯代码项目的魅力 ✨ <a class="header-anchor" href="#告别storyboard-纯代码项目的魅力-✨" aria-label="Permalink to &quot;告别Storyboard：纯代码项目的魅力 ✨&quot;">​</a></h2><p>在iOS开发中，Storyboard曾是界面设计的首选工具。然而，随着项目复杂度的增加，纯代码开发逐渐展现出其独特的优势。它提供了更精细的控制力，让你的项目结构更加清晰，并且团队协作时合并代码冲突的难度也大大降低。</p><h2 id="启动xcode-创建新项目-🚀" tabindex="-1">启动Xcode：创建新项目 🚀 <a class="header-anchor" href="#启动xcode-创建新项目-🚀" aria-label="Permalink to &quot;启动Xcode：创建新项目 🚀&quot;">​</a></h2><p>首先，打开Xcode，选择“Create a new Xcode project”。在弹出的模板选择器中，你会看到多种应用类型。对于我们的纯代码项目，请选择“App”模板。这是最基础也是最灵活的起点，让你能够完全掌控项目的每一个细节。</p><h2 id="配置项目选项-关键一步-⚙️" tabindex="-1">配置项目选项：关键一步 ⚙️ <a class="header-anchor" href="#配置项目选项-关键一步-⚙️" aria-label="Permalink to &quot;配置项目选项：关键一步 ⚙️&quot;">​</a></h2><p>接下来，你需要配置项目的基本信息。</p><ul><li><strong>Product Name (产品名称)</strong>：为你的项目起一个响亮的名字，例如“PureCodeAnimation”。</li><li><strong>Organization Identifier (组织标识符)</strong>：通常是你的公司或个人域名的反向形式，例如“com.yourcompany”。</li><li><strong>Interface (界面)</strong>：这是最关键的设置！请务必选择“Storyboard”旁边的“None”。这将告诉Xcode你将完全通过代码来构建用户界面。</li><li><strong>Language (语言)</strong>：选择“Swift”，这是iOS应用开发的现代语言。</li><li><strong>Life Cycle (生命周期)</strong>：选择“UIKit App Delegate”。这确保了你的应用生命周期由传统的AppDelegate管理，而不是新的SwiftUI App。</li></ul><h2 id="移除storyboard文件-彻底告别-🗑️" tabindex="-1">移除Storyboard文件：彻底告别 🗑️ <a class="header-anchor" href="#移除storyboard文件-彻底告别-🗑️" aria-label="Permalink to &quot;移除Storyboard文件：彻底告别 🗑️&quot;">​</a></h2><p>项目创建成功后，你会发现Xcode仍然生成了一个<code>Main.storyboard</code>文件。由于我们选择了纯代码开发，这个文件已经不再需要了。</p><ol><li>在项目导航器中找到并选中<code>Main.storyboard</code>。</li><li>右键点击它，选择“Delete”。</li><li>在弹出的对话框中，选择“Move to Trash”以彻底删除。</li></ol><h2 id="配置info-plist-指明入口-📝" tabindex="-1">配置Info.plist：指明入口 📝 <a class="header-anchor" href="#配置info-plist-指明入口-📝" aria-label="Permalink to &quot;配置Info.plist：指明入口 📝&quot;">​</a></h2><p>删除了Storyboard文件后，Xcode需要知道你的应用从哪里开始加载界面。这需要在<code>Info.plist</code>文件中进行配置。</p><ul><li>打开<code>Info.plist</code>文件。</li><li>找到“Application Scene Manifest”条目，展开它。</li><li>展开“Scene Configuration” -&gt; “Application Session Role” -&gt; “Item 0 (Default Configuration)”。</li><li>你会看到一个名为“Storyboard Name”的键。选中它并点击减号（-）将其删除。</li></ul><p>通过这些步骤，你已经成功创建了一个完全基于纯代码的Xcode项目。现在，你拥有了一个干净、灵活的画布，可以尽情发挥你的创意，用代码构建出令人惊叹的动画和交互！这为你后续深入学习UIKit动画和手势打下了坚实的基础。💪</p>',15)]))}const u=a(i,[["render",d]]);export{b as __pageData,u as default};
